"""Build a compact educational report PDF from executed benchmark outputs."""
from pathlib import Path
import csv
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'research'/'AIR-001-report.pdf'
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='Body',fontName='Helvetica',fontSize=10.3,leading=15,spaceAfter=8,textColor=colors.HexColor('#263442')))
styles.add(ParagraphStyle(name='Section',fontName='Helvetica-Bold',fontSize=15,leading=19,spaceBefore=12,spaceAfter=8,textColor=colors.HexColor('#173753')))
styles.add(ParagraphStyle(name='CoverTitle',fontName='Helvetica-Bold',fontSize=29,leading=34,spaceAfter=14,textColor=colors.HexColor('#173753')))
styles.add(ParagraphStyle(name='SmallNote',fontName='Helvetica',fontSize=8.5,leading=12,spaceAfter=7,textColor=colors.HexColor('#526475')))
styles.add(ParagraphStyle(name='Kicker',fontName='Helvetica-Bold',fontSize=10,leading=13,spaceAfter=12,textColor=colors.HexColor('#177F86')))


def p(text,style='Body'): return Paragraph(text,styles[style])
def header(title): return p(title,'Section')
def table(rows,widths):
    t=Table(rows,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#173753')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTNAME',(0,1),(-1,-1),'Helvetica'),('FONTSIZE',(0,0),(-1,-1),9),('LEADING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#F1F5F7'),colors.white]),('LINEBELOW',(0,-1),(-1,-1),.5,colors.HexColor('#B0BEC9')),('VALIGN',(0,0),(-1,-1),'TOP')]))
    return t

def footer(canvas,doc):
    w,h=A4;canvas.setStrokeColor(colors.HexColor('#D4DDE4'));canvas.line(42,39,w-42,39);canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#526475'));canvas.drawString(42,25,'AIR-001  |  Educational research report  |  V1 development baseline');canvas.drawRightString(w-42,25,str(doc.page))

rows=list(csv.DictReader((ROOT/'results'/'summary.csv').open()))
lookup={(r['experiment'],r['configuration']):r for r in rows}
selected=[('EXP-001','OLS vs GD','OLS test MSE'),('EXP-002','logistic','Logistic test accuracy'),('EXP-002','Gaussian NB','Gaussian NB test accuracy'),('EXP-003','k=9, euclidean','KNN k=9 validation accuracy'),('EXP-004','depth=3','Tree depth=3 validation accuracy'),('EXP-005','trees=7, features=2','Forest validation accuracy'),('EXP-006','k-means++','K-means++ training inertia'),('EXP-007','components=2','PCA test reconstruction MSE')]
tab=[['Metric / configuration','NumPy','Reference']]
for exp,c,label in selected:
    r=lookup[exp,c];tab.append([label,f"{float(r['ours_mean']):.6f}",f"{float(r['reference_mean']):.6f}"])
story=[p('PUBLIC AI RESEARCH PROJECT 001','Kicker'),p('Machine Learning<br/>From Scratch','CoverTitle'),p('Controlled synthetic experiments with independent NumPy implementations and scikit-learn references.'),p('Repository: MarkRizam/machine-learning-from-scratch<br/>24 November 2026 | Experimental implementation, release review pending','SmallNote'),Spacer(1,10),table([['Algorithm families','Experiments','Local tests','Notebooks'],['9','8','37 passed','9 executed']],[127,127,127,127]),header('Abstract'),p('Nine classical machine learning and optimization families were implemented in NumPy. Eight experiments generated 78 configuration-and-seed records using three deterministic synthetic datasets per experiment setting. Two runs matched within absolute numerical tolerance 1e-10. Regression, logistic classification, KNN, Gaussian Naive Bayes and PCA closely agreed with reference implementations within the evaluated scope. Trees, forests and clustering can differ because of initialization, splitting and voting rules.'),header('Research question'),p('How closely can transparent implementations reproduce the behavior of established machine learning libraries under controlled synthetic conditions?'),header('Scope'),p('This work is educational algorithm reproduction and comparative evaluation. It is not a novel algorithm, peer-reviewed publication, production-grade library or evidence of general performance superiority.'),header('Reproducibility'),p('Linux x86_64; Python 3.13.5; NumPy 2.3.5; SciPy 1.17.0; scikit-learn 1.8.0. All inputs are generated locally. No external dataset, participant data, GPU or paid API was required.'),PageBreak(),header('1. Methodology'),p('The protocol was recorded after initial implementation and correctness tests but before the benchmark runs. Seeds 11, 22 and 33 generate 200 independent rows with three normal features. Regression targets follow a linear equation plus Gaussian noise (standard deviation 0.5). Classification thresholds the sum of two features plus independent standard-normal noise.'),p('The supervised split is 120 training, 40 validation and 40 test rows. Parameter sweeps use validation only; fixed models are evaluated on test rows. PCA is fitted on training rows and evaluated by test reconstruction. Clustering uses 90 synthetic points in three separated groups and evaluates training inertia.'),header('2. Selected experimental results'),p('Means across the three seeds; accuracy expressed as a fraction. Full per-seed records and sample standard deviations are in results/benchmarks.json and results/summary.csv.'),table(tab,[290,109,109]),Spacer(1,8),Image(str(ROOT/'figures/EXP-002.png'),width=480,height=240),p('Figure 1. Test accuracy for logistic regression and Gaussian NB, mean +/- sample standard deviation over three seeds.','SmallNote'),PageBreak(),header('3. Optimization and clustering'),p('Random-init K-means reached a mean inertia of 6.587810 in the NumPy implementation and 255.557134 in the reference, reflecting an unfavorable local minimum in a reference run. These are single-restart comparisons with different random sequences; they do not demonstrate algorithmic superiority.'),p('The mean least-squares optimum half-MSE was 0.144496. With a full batch and learning rate 0.01, 100 epochs yielded 2.202856; at rate 0.05 the loss was 0.146773. With batch size 16 and rate 0.01 the result was 0.144568. Equal epoch counts do not imply equal update counts.'),Image(str(ROOT/'figures/EXP-008.png'),width=480,height=240),p('Figure 2. Final training half-MSE by batch size and learning rate, mean +/- sample SD. Reference denotes the OLS optimum.','SmallNote'),header('4. Interpretation'),p('Agreement is a scoped correctness check, not proof of general accuracy. Tree split tie handling, random sampling and voting differ; the from-scratch forest uses hard class voting rather than averaging probabilities. Three seeds are insufficient for broad statistical inference. Validation sweeps must not be interpreted as untouched test-set estimates.'),PageBreak(),header('5. Reproduction and limitations'),p('Install Python 3.13, clone the reviewed branch, create a virtual environment, then run:'),p('python -m pip install -e &quot;.[research]&quot;<br/>python -m pytest -q<br/>python -m ml_from_scratch.experiments<br/>python scripts/execute_notebooks.py','Body'),p('Set OPENBLAS_NUM_THREADS and OMP_NUM_THREADS to 1. The experiment script runs twice, comparing deterministic numeric results with absolute tolerance 1e-10 and zero relative tolerance. Runtime and cross-platform bitwise identity are not claimed.'),table([['Check','Local evidence'],['Python package','Editable install passed'],['Unit / correctness tests','37 passed'],['Experiment families','8 of 8, repeated'],['Jupyter notebooks','9 executed; initial batch interrupted, final 3 run separately'],['Docker / Ruff','Not run; tools unavailable'],['Hosted CI','Separate verification required']],[164,344]),header('Limitations and future work'),p('Small synthetic datasets only. No runtime benchmark, real-world dataset, human-participant data or clinical evaluation. The implementations are intentionally limited: binary unregularized logistic regression, hard-vote forests, fixed iteration limits, least-squares-only gradient descent and incomplete edge-case validation. Additional independent checks and fair timing studies should precede public release.'),header('References'),p('NumPy linear algebra: numpy.org/doc/stable/reference/routines.linalg.html<br/>scikit-learn user guide: scikit-learn.org/stable/user_guide.html<br/>scikit-learn evaluation: scikit-learn.org/stable/modules/model_evaluation.html','SmallNote'),p('The documentation URLs are standard reference links; live availability was not checked in the offline local runtime. Source, notebook files and exact outputs accompany this report.','SmallNote')]
SimpleDocTemplate(str(OUT),pagesize=A4,leftMargin=42,rightMargin=42,topMargin=38,bottomMargin=53,title='AIR-001 - Machine Learning From Scratch',author='Mohd Rizam Bakar').build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT)
